{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Although several studies that evaluate the effectiveness of active and passive immunization in SCI are available, conflicting findings have been reported between studies... These inconsistencies have made it impossible to draw a general conclusion in this regard. On the other hand, it is not yet clear which active and inactive immunogenic methods are more effective in improving the motor function of animals. Accordingly, there is still no conclusion on the role of passive immunization with immune cells activated by MBP or on active immunization with injection of MBP and its derivatives in the treatment of SCI in the literature.",
      "reason": "Describes the current evidence as conflicting and identifies key uncertainties (no general conclusion and unclear relative effectiveness of active vs passive methods)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Hence, the present study aims to perform a systematic review and meta-analysis to determine the effectiveness of passive or active immunization with MBP on motor recovery in animal models following SCI.",
      "reason": "Explains the need to conduct the review by stating the study aim to resolve effectiveness uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was provided that discusses similar systematic reviews and how the current review relates to them (updates/replications and citation of prior systematic reviews)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "These studies indicate that the presence of immune T cells in the injury site increases secretion of nervous growth factors, improves the tissue environment surrounding the damaged neurons, protects the remaining myelin, and eventually, leads to enhancement of motor recovery... On the other hand, administration of this protein or similar peptides, as an active immunogenic process, could have significant effects on improving motor function following SCI (14-16).",
      "reason": "Provides a brief hypothesised mechanism linking immunization/MBP to neuroprotective and regenerative effects and improved motor recovery."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or hypothesised relationships between intervention components and outcomes were reported."
    }
  ],
  "confidence": 72
}

{
